function subsets(nums: number[]): number[][] {
    // Initialize the result array to store all subsets.
    const res: number[][] = [];
    // Initialize a subset array to store the current subset being built.
    const subset: number[] = [];

    // Define the depth-first search (DFS) function.
    function dfs(i: number) {
        // Base case: If we have processed all numbers in the input array.
        if (i >= nums.length) {
            // Add a copy of the current subset to the result.
            res.push([...subset]);
            return;
        }

        // Include nums[i] in the current subset.
        subset.push(nums[i]);
        // Recursively call dfs to explore the rest of the numbers.
        dfs(i + 1);

        // Backtrack: Remove nums[i] from the current subset to explore the other branch.
        subset.pop();
        // Recursively call dfs to explore the rest of the numbers without including nums[i].
        dfs(i + 1);
    }

    // Start the DFS from the first number (index 0).
    dfs(0);
    // Return the result containing all subsets.
    return res;
}

