public static class Solution {

    public List<List<Integer>> subsets(int[] nums) {
        // Initialize the result list to store all subsets
        List<List<Integer>> res = new ArrayList<>();
        // Start the depth-first search (DFS) from index 0
        dfs(0, nums, new ArrayList<>(), res);
        // Return the list containing all subsets
        return res;
    }

    private void dfs(int i, int[] nums, List<Integer> subset, List<List<Integer>> res) {

        // Base case: If we have reached the end of the input array,
        // add the current subset to the result list.
        if (i == nums.length) {
            // Add a copy of the current subset to the result.
            // It's important to create a new ArrayList to avoid modifying the same list.
            res.add(new ArrayList<>(subset));
            return;
        }

        // Recursive case:
        // 1. Include the current element nums[i] in the subset
        subset.add(nums[i]);
        // Explore the subsets including nums[i] by moving to the next index
        dfs(i + 1, nums, subset, res);

        // 2. Exclude the current element nums[i] from the subset
        // Backtrack: Remove the last added element to explore subsets that don't include it.
        subset.remove(subset.size() - 1);
        // Explore the subsets excluding nums[i] by moving to the next index
        dfs(i + 1, nums, subset, res);
    }
}

