            // Add the current subset to the result.
            res.push_back(subset);
            return;
        }

        // Recursive case 1: Include nums[i] in the current subset.
        subset.push_back(nums[i]);
        // Explore the subsets including nums[i] by moving to the next element.
        dfs(i + 1, nums, subset, res);

        // Recursive case 2: Exclude nums[i] from the current subset.
        // Backtrack by removing nums[i] to explore subsets without it.
        subset.pop_back();
        // Explore the subsets excluding nums[i] by moving to the next element.
        dfs(i + 1, nums, subset, res);
    }
};

