function permute(nums: number[]): number[][] {
    const result: number[][] = [];

    // Base case: If the input array has only one element, return it as a single permutation.
    if (nums.length === 1) {
        return [nums.slice()]; // Create a copy to avoid modification of the original array
    }

    // Iterate through each element in the input array.
    for (let i = 0; i < nums.length; i++) {
        const n = nums.shift()!;  // Remove the first element from the array using shift() and store it in 'n'. The '!' is a non-null assertion.

        // Recursively generate permutations of the remaining elements.
        const perms = permute(nums);

        // For each permutation of the remaining elements, add the removed element 'n' to the end.
        for (const perm of perms) {
            perm.push(n); // Append 'n' to the end of the current permutation.
        }

        // Add the modified permutations to the result array.
        result.push(...perms); // Use the spread operator to add all permutations from 'perms' to 'result'.

        // Restore the removed element to its original position in the array to maintain the original state for the next iteration.
        nums.push(n); // Add 'n' back to the end of the array to restore the original order.
    }

    return result; // Return the array of all generated permutations.
}

