public static class Solution {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();

        // Base case: If the input array has only one element,
        // return a list containing a list with that element.
        if (nums.length == 1) {
            List<Integer> baseList = new ArrayList<>();
            baseList.add(nums[0]);
            List<List<Integer>> baseResult = new ArrayList<>();
            baseResult.add(new ArrayList<>(baseList)); // Create a new list to avoid modification issues
            return baseResult;
        }

        for (int i = 0; i < nums.length; i++) {
            // Create a new array 'remainingNums' that excludes nums[i].
            int[] remainingNums = new int[nums.length - 1];
            int index = 0;
            for (int j = 0; j < nums.length; j++) {
                if (i != j) {
                    remainingNums[index++] = nums[j];
                }
            }

            // Recursively find permutations of the remaining numbers.
            List<List<Integer>> subPermutations = permute(remainingNums);

            // Add the removed number to each sub-permutation.
            for (List<Integer> subPermutation : subPermutations) {
                subPermutation.add(nums[i]);
            }

            // Add all modified sub-permutations to the result.
            result.addAll(subPermutations);
        }

        return result;
    }
}

