class Solution {
public:
    vector<vector<int>> permute(vector<int>& nums) {
        // This vector will store all the generated permutations.
        vector<vector<int>> result;

        // Base case: If the input vector contains only one element,
        // return a vector containing a vector with that single element.
        if (nums.size() == 1) {
            return {nums};
        }

        // Iterate through each element in the input vector.
        for (int i = 0; i < nums.size(); i++) {
            // Create a new vector to hold the remaining numbers, excluding the current number (nums[i]).
            vector<int> remainingNums;
            // Iterate through the original nums vector to build remainingNums.
            for (int j = 0; j < nums.size(); j++) {
                // If the index j is not equal to the current index i,
                // add the number at index j to the remainingNums vector.
                if (i != j) {
                    remainingNums.push_back(nums[j]);
                }
            }

            // Recursively call the permute function with the remainingNums vector
            // to get all permutations of the remaining numbers.
            vector<vector<int>> subPermutations = permute(remainingNums);

            // After getting the permutations of the remaining numbers,
            // add the number that was excluded (nums[i]) to each of these permutations.
            for (auto &perm : subPermutations) {
                perm.push_back(nums[i]);
            }

            // Insert the permutations obtained from the subproblem into the result vector.
            // This combines the permutations of the remaining numbers with the current number.
            result.insert(result.end(), subPermutations.begin(), subPermutations.end());
        }

        // After iterating through all the numbers in the input vector,
        // the result vector will contain all possible permutations.
        return result;
    }
};

