function combine(n: number, k: number): number[][] {
  // res will store all valid combinations.
  const res: number[][] = [];

  // Recursive backtracking function to generate combinations.
  function backtrack(start: number, comb: number[]) {
    // Base case: If the combination 'comb' has reached the desired length 'k',
    // add it to the result 'res'.
    if (comb.length === k) {
      res.push([...comb]); // Create a copy to avoid modification issues.
      return;
    }

    // Iterate from the 'start' number up to 'n'.
    // 'i' represents the next number to include in the combination.
    for (let i = start; i <= n; i++) {
      // Include 'i' in the current combination.
      comb.push(i);

      // Recursively call 'backtrack' to explore further combinations,
      // starting from the next number (i + 1).
      backtrack(i + 1, comb);

      // Backtrack: Remove 'i' from the current combination to explore
      // other possibilities.
      comb.pop();
    }
  }

  // Initiate the backtracking process, starting from number 1
  // with an initially empty combination.
  backtrack(1, []);
  return res;
}

