public static class Solution {
    public List<List<Integer>> combine(int n, int k) {
        // Initialize the list to store the resulting combinations.
        List<List<Integer>> res = new ArrayList<>();
        // Call the backtrack helper function to generate combinations.
        backtrack(n, k, 1, new ArrayList<>(), res);
        // Return the list of combinations.
        return res;
    }

    private void backtrack(int n, int k, int start, List<Integer> comb, List<List<Integer>> res) {
        // Base case: If the combination has reached the desired length k, add it to the result.
        if (comb.size() == k) {
            res.add(new ArrayList<>(comb)); // Add a copy of the current combination to the result
            return;
        }

        // Iterate from the current starting number up to n.
        for (int i = start; i <= n; i++) {
            // Add the current number to the combination.
            comb.add(i);

            // Recursively call backtrack with the next number (i + 1) as the new starting point.
            backtrack(n, k, i + 1, comb, res);

            // Backtrack: Remove the last added number to explore other combinations.
            comb.remove(comb.size() - 1);
        }
    }
}

