function exist(board: string[][], word: string): boolean {
    // Get the number of rows in the board.
    const ROWS = board.length;
    // Get the number of columns in the board.
    const COLS = board[0].length;

    // Use a Set to store the cells in the current path to prevent cycles.
    const path = new Set<string>();

    // Depth-First Search function to explore the board.
    function dfs(r: number, c: number, i: number): boolean {
        // If we have found all characters in the word, return true.
        if (i === word.length) {
            return true;
        }

        // Check if the current cell is out of bounds, if the character at the current cell
        // does not match the character at the current index in the word, or if the current cell
        // is already in the current path.
        if (
            r < 0 ||
            c < 0 ||
            r >= ROWS ||
            c >= COLS ||
            board[r][c] !== word[i] ||
            path.has(`${r},${c}`)
        ) {
            return false;
        }

        // Add the current cell to the path.
        path.add(`${r},${c}`);

        // Recursively call DFS on the adjacent cells.
        const res = 
            dfs(r + 1, c, i + 1) || // Down
            dfs(r - 1, c, i + 1) || // Up
            dfs(r, c + 1, i + 1) || // Right
            dfs(r, c - 1, i + 1);   // Left

        // Remove the current cell from the path (backtrack).
        path.delete(`${r},${c}`);

        // Return whether the word was found.
        return res;
    }

    // Iterate over all cells in the board.
    for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
            // If the DFS function returns true for the current cell, return true.
            if (dfs(r, c, 0)) {
                return true;
            }
        }
    }

    // If the word was not found, return false.
    return false;
}

