public static class Solution {
    public boolean exist(char[][] board, String word) {
        // Get the dimensions of the board.
        int ROWS = board.length;
        int COLS = board[0].length;

        // Create a boolean array to keep track of the cells visited in the current path.
        boolean[][] path = new boolean[ROWS][COLS];

        // Iterate through each cell in the board to start a DFS from that cell.
        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                // If the DFS starting from this cell finds the word, return true.
                if (dfs(board, r, c, word, 0, path)) {
                    return true;
                }
            }
        }

        // If the word is not found after checking all possible starting cells, return false.
        return false;
    }

    private boolean dfs(char[][] board, int r, int c, String word, int i, boolean[][] path) {
        // If the index i reaches the length of the word, it means the word has been found.
        if (i == word.length()) {
            return true;
        }

        // Check if the current cell is out of bounds, if the character at the cell
        // doesn't match the current character in the word, or if the cell has already
        // been visited in the current path.
        if (
            r < 0 ||
            c < 0 ||
            r >= board.length ||
            c >= board[0].length ||
            board[r][c] != word.charAt(i) ||
            path[r][c]
        ) {
            return false;
        }

        // Mark the current cell as visited in the current path.
        path[r][c] = true;

        // Recursively call DFS on the adjacent cells (up, down, left, right).
        boolean res =
            dfs(board, r + 1, c, word, i + 1, path) ||
            dfs(board, r - 1, c, word, i + 1, path) ||
            dfs(board, r, c + 1, word, i + 1, path) ||
            dfs(board, r, c - 1, word, i + 1, path);

        // Backtrack by marking the current cell as unvisited, so that it can be
        // visited in another path.
        path[r][c] = false;

        // Return true if any of the recursive calls returned true, otherwise return false.
        return res;
    }
}

