class Solution {
public:
    bool exist(vector<vector<char>>& board, string word) {
        // Get the number of rows and columns in the board.
        int ROWS = board.size();
        int COLS = board[0].size();

        // Create a 2D boolean vector to keep track of the cells visited in the current path.
        // Initialize all cells to false, indicating that no cell has been visited yet.
        vector<vector<bool>> path(ROWS, vector<bool>(COLS, false));

        // Iterate through each cell in the board.
        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                // For each cell, start a Depth-First Search (DFS) to find the word.
                // If the DFS returns true, it means the word is found, so return true.
                if (dfs(board, r, c, word, 0, path)) {
                    return true;
                }
            }
        }

        // If the word is not found after searching all cells, return false.
        return false;
    }

private:
    // Depth-First Search (DFS) function to find the word in the board.
    bool dfs(vector<vector<char>>& board, int r, int c, string& word, int i, vector<vector<bool>>& path) {
        // Base case: If the index i reaches the end of the word, it means the word is found.
        if (i == word.length()) {
            return true;
        }

        // Base case: If the current cell is out of bounds, the character at the current cell
        // does not match the character at the current index in the word, or the cell has already
        // been visited in the current path, then return false.
        if (
            r < 0 ||
            c < 0 ||
            r >= board.size() ||
            c >= board[0].size() ||
            board[r][c] != word[i] ||
            path[r][c]
        ) {
            return false;
        }

        // Mark the current cell as visited in the current path.
        path[r][c] = true;

        // Recursively call DFS in all four directions (up, down, left, right).
        // If any of the recursive calls return true, it means the word is found, so return true.
        bool res =
            dfs(board, r + 1, c, word, i + 1, path) ||
            dfs(board, r - 1, c, word, i + 1, path) ||
            dfs(board, r, c + 1, word, i + 1, path) ||
            dfs(board, r, c - 1, word, i + 1, path);

        // Backtrack: Mark the current cell as unvisited after exploring all four directions.
        // This allows the cell to be visited in other paths.
        path[r][c] = false; // backtrack

        // Return the result of the DFS.
        return res;
    }
};

