function solveNQueens(n: number): string[][] {
  // Use sets to keep track of columns and diagonals occupied by queens.
  const col = new Set<number>();
  const posDiag = new Set<number>(); // r + c
  const negDiag = new Set<number>(); // r - c

  // Store the resulting board configurations.
  const res: string[][] = [];

  // Initialize the board with empty cells ('.').
  const board: string[][] = Array.from({ length: n }, () => Array(n).fill('.'));

  // Recursive backtracking function to explore possible queen placements.
  function backtrack(r: number): void {
    // Base case: If all rows are filled, a solution is found.
    if (r === n) {
      // Create a copy of the board to store in the result.
      const copy = board.map(row => row.join(""));
      res.push(copy);
      return;
    }

    // Iterate through each column in the current row.
    for (let c = 0; c < n; c++) {
      // Check if placing a queen in the current cell is safe.
      // A cell is unsafe if there is a queen in the same column or diagonal.
      if (col.has(c) || posDiag.has(r + c) || negDiag.has(r - c)) {
        continue; // Skip to the next column if the current cell is unsafe.
      }

      // Place the queen in the current cell (r, c).
      col.add(c); // Mark the column as occupied.
      posDiag.add(r + c); // Mark the positive diagonal as occupied.
      negDiag.add(r - c); // Mark the negative diagonal as occupied.
      board[r][c] = "Q"; // Place the queen on the board.

      // Recursively try to place a queen in the next row.
      backtrack(r + 1);

      // Backtrack: Remove the queen from the current cell and unmark the column and diagonals.
      col.delete(c);
      posDiag.delete(r + c);
      negDiag.delete(r - c);
      board[r][c] = ".";
    }
  }

  // Start the backtracking process from the first row (r = 0).
  backtrack(0);
  return res; // Return the list of solutions.
}

