    public List<List<String>> solveNQueens(int n) {
        // Initialize the result list to store all valid board configurations.
        List<List<String>> res = new ArrayList<>();

        // Create an empty n x n board represented as a 2D char array.
        char[][] board = new char[n][n];

        // Initialize the board with empty cells ('.').
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                board[i][j] = '.';
            }
        }

        // Use sets to keep track of columns and diagonals under attack.
        Set<Integer> col = new HashSet<>(); // Columns
        Set<Integer> posDiag = new HashSet<>(); // Positive diagonals (row + col)
        Set<Integer> negDiag = new HashSet<>(); // Negative diagonals (row - col)

        // Start the backtracking algorithm from the first row (row 0).
        backtrack(board, 0, col, posDiag, negDiag, res, n);

        // Return the list of valid board configurations.
        return res;
    }

    private void backtrack(char[][] board, int r, Set<Integer> col, Set<Integer> posDiag, Set<Integer> negDiag, List<List<String>> res, int n) {
        // Base case: If we have reached the last row, a valid solution is found.
        if (r == n) {
            // Create a list of strings representing the board.
            List<String> solution = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                solution.add(new String(board[i])); // Convert each row to a string
            }
            // Add the solution to the result list.
            res.add(solution);
            return;
        }

        // Iterate over each column in the current row.
        for (int c = 0; c < n; c++) {
            // Check if placing a queen in the current cell (r, c) is valid.
            if (col.contains(c) || posDiag.contains(r + c) || negDiag.contains(r - c)) {
                // If the cell is under attack, skip to the next column.
                continue;
            }

            // If the placement is valid, add the column and diagonals to the sets.
            col.add(c);
            posDiag.add(r + c);
            negDiag.add(r - c);

            // Place a queen in the current cell.
            board[r][c] = 'Q';

            // Recursively call backtrack for the next row.
            backtrack(board, r + 1, col, posDiag, negDiag, res, n);

            // Backtrack: Remove the queen and update the sets to explore other possibilities.
            col.remove(c);
            posDiag.remove(r + c);
            negDiag.remove(r - c);
            board[r][c] = '.';
        }
    }
}

