public:
    vector<vector<string>> solveNQueens(int n) {
        // res stores all possible board configurations that satisfy the N-Queens problem
        vector<vector<string>> res;
        // board represents the current board configuration (n x n), initialized with empty cells ('.')
        vector<string> board(n, string(n, '.'));

        // col keeps track of columns where queens are already placed (for O(1) lookup)
        unordered_set<int> col;
        // posDiag keeps track of positive diagonals where queens are already placed (r + c is constant along a positive diagonal)
        unordered_set<int> posDiag; // r + c
        // negDiag keeps track of negative diagonals where queens are already placed (r - c is constant along a negative diagonal)
        unordered_set<int> negDiag; // r - c

        // Start the backtracking algorithm from the first row (r = 0)
        backtrack(board, 0, col, posDiag, negDiag, res, n);
        // Return the result containing all valid board configurations
        return res;
    }

private:
    void backtrack(vector<string>& board,
                   int r,
                   unordered_set<int>& col,
                   unordered_set<int>& posDiag,
                   unordered_set<int>& negDiag,
                   vector<vector<string>>& res,
                   int n) {

        // Base case: If we have filled all rows (r == n), it means we have a valid configuration.
        if (r == n) {
            // Add the current board configuration to the result.
            res.push_back(board);
            return;
        }

        // Iterate through each column in the current row.
        for (int c = 0; c < n; c++) {
            // Check if placing a queen at (r, c) is valid. If any of the conditions are true, it's not a valid placement.
            if (col.count(c) || posDiag.count(r + c) || negDiag.count(r - c)) {
                // If the position is not valid, continue to the next column.
                continue;
            }

            // Place the queen at (r, c):
            // Mark the current column, positive diagonal, and negative diagonal as occupied.
            col.insert(c);
            posDiag.insert(r + c);
            negDiag.insert(r - c);
            board[r][c] = 'Q';

            // Recursively call the backtrack function to place queens in the next row.
            backtrack(board, r + 1, col, posDiag, negDiag, res, n);

            // Backtrack: Remove the queen from (r, c) and clear the occupied marks.
            // This is necessary to explore other possible configurations.
            col.erase(c);
            posDiag.erase(r + c);
            negDiag.erase(r - c);
            board[r][c] = '.';
        }
    }
};

