function isValidSudoku(board: string[][]): boolean {
    // Initialize maps to store the numbers present in each row, column, and 3x3 sub-grid.
    const rows: Map<number, Set<string>> = new Map();
    const cols: Map<number, Set<string>> = new Map();
    const squares: Map<string, Set<string>> = new Map();

    // Iterate through each cell of the Sudoku board.
    for (let r = 0; r < 9; r++) {
        for (let c = 0; c < 9; c++) {
            const value = board[r][c];

            // If the cell is empty, continue to the next cell.
            if (value === ".") continue;

            // Calculate the key for the 3x3 sub-grid to which the cell belongs.
            const squareKey = `${Math.floor(r / 3)},${Math.floor(c / 3)}`;

            // Check if the current number already exists in the row, column, or sub-grid.
            if (
                (rows.get(r)?.has(value)) ||
                (cols.get(c)?.has(value)) ||
                (squares.get(squareKey)?.has(value))
            ) {
                // If a duplicate is found, the Sudoku board is invalid.
                return false;
            }

            // If the row/col/square doesn't exist in the map, create a new Set for it
            if (!rows.has(r)) rows.set(r, new Set());
            if (!cols.has(c)) cols.set(c, new Set());
            if (!squares.has(squareKey)) squares.set(squareKey, new Set());

            // Add the current number to the sets for the corresponding row, column, and sub-grid.
            rows.get(r)!.add(value);
            cols.get(c)!.add(value);
            squares.get(squareKey)!.add(value);
        }
    }

    // If no duplicates are found after iterating through all cells, the Sudoku board is valid.
    return true;
}

