public static class Solution {
    public boolean isValidSudoku(char[][] board) {
        // Map to store numbers in each row. Key is row index, Value is a set of characters.
        Map<Integer, Set<Character>> rows = new HashMap<>();
        // Map to store numbers in each column. Key is column index, Value is a set of characters.
        Map<Integer, Set<Character>> cols = new HashMap<>();
        // Map to store numbers in each 3x3 sub-grid. Key is a string "row/3,col/3", Value is a set of characters.
        Map<String, Set<Character>> squares = new HashMap<>();

        // Iterate through each cell in the Sudoku board.
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                // Get the character value of the current cell.
                char value = board[r][c];

                // If the cell is empty ('.'), skip to the next cell.
                if (value == '.') continue;

                // Calculate the key for the 3x3 sub-grid to which the current cell belongs.
                String squareKey = r / 3 + "," + c / 3;

                // Check if the current value already exists in the row, column, or sub-grid.
                if (
                    (rows.containsKey(r) && rows.get(r).contains(value)) ||
                    (cols.containsKey(c) && cols.get(c).contains(value)) ||
                    (squares.containsKey(squareKey) && squares.get(squareKey).contains(value))
                ) {
                    // If the value already exists, the Sudoku board is invalid.
                    return false;
                }

                // If the value does not exist, add it to the row, column, and sub-grid sets.
                rows.computeIfAbsent(r, k -> new HashSet<>()).add(value);
                cols.computeIfAbsent(c, k -> new HashSet<>()).add(value);
                squares.computeIfAbsent(squareKey, k -> new HashSet<>()).add(value);
            }
        }

        // If no violations were found, the Sudoku board is valid.
        return true;
    }
}

