function singleNumber(nums: number[]): number {
  // Initialize a variable to store the result of XORing all numbers.
  // We start with 0 because 0 XOR any number is the number itself (identity property).
  let result = 0;

  // Iterate through the array and XOR each number with the current result.
  for (let i = 0; i < nums.length; i++) {
    // The XOR operation (^) has the property that a ^ a = 0 and a ^ 0 = a.
    // By XORing all numbers, the pairs cancel each other out (a ^ a = 0),
    // leaving only the single number that appears once.
    result ^= nums[i];
  }

  // Return the final result, which is the single number that appears only once.
  return result;
}

