public static class Solution {
    /**

     * @param nums the input array of integers
     * @return the single element that appears only once
     */
    public int singleNumber(int[] nums) {
        // Initialize the result variable to 0.  This will hold the XOR of all elements.
        int res = 0;

        // Iterate through each number 'n' in the input array 'nums'.
        for (int n : nums) {
            // Perform XOR operation between 'res' and the current number 'n',
            // and store the result back in 'res'.
            // XOR has the property that a ^ a = 0 and a ^ 0 = a.
            // Therefore, if a number appears twice, it will cancel itself out.
            res = n ^ res;
        }

        // After XORing all numbers, 'res' will contain the single number that appears only once.
