function countBits(n: number): number[] {
    // Initialize a dynamic programming array to store the number of set bits for each number from 0 to n.
    const dp: number[] = new Array(n + 1).fill(0);
    // Initialize the offset to 1. The offset represents the largest power of 2 less than or equal to the current number.
    let offset = 1;

    // Iterate through numbers from 1 to n.
    for (let i = 1; i <= n; i++) {
        // If the current number i is a power of 2, update the offset.
        if (offset * 2 === i) {
            offset = i;
        }

        // Calculate the number of set bits for the current number i using the dynamic programming approach.
        // The number of set bits in i is 1 (for the most significant bit) plus the number of set bits in (i - offset).
        dp[i] = 1 + dp[i - offset];
    }

    // Return the dynamic programming array containing the number of set bits for each number from 0 to n.
    return dp;
}

