function subsets(nums: number[]): number[][] {
    // Initialize an empty array to store the resulting subsets.
    const res: number[][] = [];
    // Get the number of elements in the input array.
    const n = nums.length;

    // Iterate through all possible subsets using a bitmask approach.
    // The outer loop goes from 0 to 2^n - 1.
    for (let mask = 0; mask < (1 << n); mask++) {
        // Initialize an empty array to store the current subset.
        const subset: number[] = [];

        // Iterate through the elements of the input array.
        for (let i = 0; i < n; i++) {
            // Check if the i-th bit is set in the current mask.
            // If (mask & (1 << i)) is non-zero, it means the i-th bit is set.
            if (mask & (1 << i)) {
                // If the i-th bit is set, add the i-th element of the input array to the current subset.
                subset.push(nums[i]);
            }
        }

        // Add the generated subset to the result list.
        res.push(subset);
    }

    // Return the complete list of subsets.
    return res;
}

