function findKthLargest(nums: number[], k: number): number {
    // Convert k to find the kth smallest element (index from the beginning)
    k = nums.length - k;

    // QuickSelect function to find the kth smallest element in the subarray nums[l...r]
    function quickSelect(l: number, r: number): number {
        // Choose the rightmost element as the pivot
        const pivot = nums[r];
        // p is the index for placing elements smaller than the pivot
        let p = l;

        // Iterate through the subarray from left to right (excluding the pivot)
        for (let i = l; i < r; i++) {
            // If the current element is less than or equal to the pivot
            if (nums[i] <= pivot) {
                // Swap nums[i] with nums[p]
                [nums[p], nums[i]] = [nums[i], nums[p]];
                // Increment p to point to the next position for smaller elements
                p++;
            }
        }

        // Swap the pivot with the element at index p
        [nums[p], nums[r]] = [nums[r], nums[p]];

        // Now the pivot is in its correct sorted position (index p)
        // If p is greater than k, the kth smallest element is in the left subarray
        if (p > k) {
            return quickSelect(l, p - 1);
        } else if (p < k) {
            // If p is less than k, the kth smallest element is in the right subarray
            return quickSelect(p + 1, r);
        } else {
            // If p is equal to k, the pivot element is the kth smallest element
            return nums[p];
        }
    }

    // Call quickSelect with the entire array and the target index k
    return quickSelect(0, nums.length - 1);
}

