public static class Solution {
    public int findKthLargest(int[] nums, int k) {
        // Convert k to the index from the beginning of the array if it were sorted.
        // For example, if we want the 2nd largest element in an array of size 5,
        // we are looking for the element at index 5 - 2 = 3.
        k = nums.length - k;

        // Call the quickSelect helper function to find the kth smallest element
        // (which is the same as the (nums.length - k)th largest element).
        return quickSelect(nums, 0, nums.length - 1, k);
    }

    private int quickSelect(int[] nums, int l, int r, int k) {
        // Choose the rightmost element as the pivot.
        int pivot = nums[r];
        // p is the index where elements smaller than or equal to the pivot will be placed.
        int p = l;

        // Iterate through the array from l to r-1.
        for (int i = l; i < r; i++) {
            // If the current element is less than or equal to the pivot,
            if (nums[i] <= pivot) {
                // Swap the current element with the element at index p.
                swap(nums, p, i);
                // Increment p to point to the next position for elements smaller than the pivot.
                p++;
            }
        }

        // After the loop, swap the pivot with the element at index p.
        // This places the pivot in its correct sorted position.
        swap(nums, p, r);

        // Now, check the position of the pivot (p) relative to k.
        // If p is greater than k, the kth smallest element is in the left subarray.
        if (p > k) {
            return quickSelect(nums, l, p - 1, k);
        // If p is less than k, the kth smallest element is in the right subarray.
        } else if (p < k) {
            return quickSelect(nums, p + 1, r, k);
        // If p is equal to k, the pivot is the kth smallest element, so return it.
        } else {
            return nums[p];
        }
    }

    private void swap(int[] nums, int i, int j) {
        // Helper function to swap two elements in the array.
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

