class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        // Convert k to find the kth smallest element.  The kth largest element
        // is the same as the (n - k)th smallest element where n is the size of the array.
        k = nums.size() - k;
        // Call the quickSelect algorithm to find the kth smallest element in the array.
        return quickSelect(nums, 0, nums.size() - 1, k);
    }

private:
    // Recursive helper function to find the kth smallest element using the QuickSelect algorithm.
    int quickSelect(vector<int>& nums, int l, int r, int k) {
        // Choose the last element as the pivot.
        int pivot = nums[r];
        // Initialize the partition index.
        int p = l;

        // Iterate through the array from the left bound to the right bound (exclusive).
        for (int i = l; i < r; i++) {
            // If the current element is less than or equal to the pivot,
            if (nums[i] <= pivot) {
                // Swap the current element with the element at the partition index.
                swap(nums[p], nums[i]);
                // Increment the partition index.
                p++;
            }
        }

        // After the loop, swap the pivot element with the element at the partition index.
        // This places the pivot element in its correct sorted position.
        swap(nums[p], nums[r]);

        // Now, check if the partition index is equal to k.
        // If p > k, the kth smallest element is in the left partition.
        if (p > k) {
            return quickSelect(nums, l, p - 1, k);
        } 
        // If p < k, the kth smallest element is in the right partition.
        else if (p < k) {
            return quickSelect(nums, p + 1, r, k);
        } 
        // If p == k, the kth smallest element is the element at the partition index.
        else {
            return nums[p];
        }
    }
};

